gbgL(){return"\u0412 \u043f\u0438\u043b\u043e\u0442\u0430 \u043e\u0431\u0435\u043a\u0442\u0438\u0442\u0435 \u0441\u0435 \u043f\u043e\u0434\u0440\u0435\u0436\u0434\u0430\u0442 \u043f\u043e \u0440\u0430\u0437\u0441\u0442\u043e\u044f\u043d\u0438\u0435, \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u043c\u044f\u0441\u0442\u043e \u0438 \u0446\u0435\u043d\u0430; \u043e\u0446\u0435\u043d\u043a\u0438\u0442\u0435 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0430\u0442."},
gbgK(){return"\u041a\u0430\u043a\u0432\u043e \u0441\u0435 \u043f\u043e\u043a\u0430\u0437\u0432\u0430 \u0437\u0430 \u0442\u0435\u0431"},
gbgJ(){return"\u0421\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043e\u0442\u043e \u0442\u0438 \u0438\u043c\u0435 \u0438 \u0438\u043d\u0438\u0446\u0438\u0430\u043b \u0438 \u043c\u0435\u0441\u0435\u0446\u044a\u0442 \u043d\u0430 \u043f\u0440\u0435\u0441\u0442\u043e\u044f; \u043d\u0438\u043a\u043e\u0433\u0430 \u043d\u043e\u043c\u0435\u0440\u044a\u0442 \u043d\u0430 \u043a\u043e\u043b\u0430\u0442\u0430, \u0434\u0435\u043d\u044f\u0442 \u0438\u043b\u0438 \u0447\u0430\u0441\u044a\u0442. \u041e\u0431\u0435\u043a\u0442\u044a\u0442 \u043d\u0435 \u0432\u0438\u0436\u0434\u0430 \u043a\u043e\u0439 \u0435 \u043f\u0438\u0441\u0430\u043b. \u041e\u0446\u0435\u043d\u043a\u0430\u0442\u0430 \u0435 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u0430 24 \u043c\u0435\u0441\u0435\u0446\u0430."},
gamg(){return"\u041e\u0431\u0438\u0434\u043d\u043e, \u043a\u043b\u0435\u0432\u0435\u0442\u043d\u0438\u0447\u0435\u0441\u043a\u043e, \u0437\u0430\u043f\u043b\u0430\u0448\u0438\u0442\u0435\u043b\u043d\u043e \u0438\u043b\u0438 \u0441 \u043e\u043c\u0440\u0430\u0437\u0430"},
