gbcg(){return"\u0412 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e"},
bch(a){return"\u0412 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\u0442\u043e \u0438\u043b\u0438 \u043d\u0430 \u043c\u044f\u0441\u0442\u043e: "+a},
gbci(){return"\u0432 \u0431\u0440\u043e\u0439"},
gbcj(){return"\u0441 \u043a\u0430\u0440\u0442\u0430 \u043d\u0430 \u043c\u044f\u0441\u0442\u043e"},
